22	export async function generateMetadata({ params }: Params): Promise<Metadata> {
23	  const { slug } = await params;
24	  const post = await getPublishedPost(slug);
25	  if (!post) return { title: "Post not found" };
26	
27	  const title = post.seoTitle || post.title;
28	  const description = post.seoDescription || post.excerpt || `${post.title} — a guide from the Nxeon blog.`;
29	  // Absolute cover URL for social cards, when the post has one.
30	  const ogImage = post.coverImage
31	    ? post.coverImage.startsWith("http")
32	      ? post.coverImage
33	      : `${APP_URL}${post.coverImage}`
34	    : undefined;
35	  return {
36	    title,
37	    description,
38	    alternates: { canonical: `/blog/${post.slug}` },
39	    openGraph: {
40	      type: "article",
41	      title,
42	      description,
43	      url: `${APP_URL}/blog/${post.slug}`,
44	      publishedTime: (post.publishedAt ?? post.createdAt).toISOString(),
45	      modifiedTime: post.updatedAt.toISOString(),
46	      authors: [post.author],
47	      tags: post.tags,
48	      ...(ogImage ? { images: [ogImage] } : {}),
49	    },
50	    twitter: { card: "summary_large_image", title, description, ...(ogImage ? { images: [ogImage] } : {}) },
51	  };
52	}
