59	/* ── reading progress (0→1) across the article body ──────────────────────── */
60	function useReadingProgress<T extends HTMLElement>() {
61	  const ref = useRef<T | null>(null);
62	  const [p, setP] = useState(0);
63	  useEffect(() => {
64	    const el = ref.current;
65	    if (!el) return;
66	    let raf = 0;
67	    const compute = () => {
68	      raf = 0;
69	      const r = el.getBoundingClientRect();
70	      const vh = window.innerHeight || 1;
71	      const total = r.height - vh;
72	      const travelled = -r.top;
73	      setP(total <= 0 ? 1 : Math.max(0, Math.min(1, travelled / total)));
74	    };
75	    const onScroll = () => {
76	      if (!raf) raf = requestAnimationFrame(compute);
77	    };
78	    compute();
79	    window.addEventListener("scroll", onScroll, { passive: true });
80	    window.addEventListener("resize", onScroll, { passive: true });
81	    return () => {
82	      window.removeEventListener("scroll", onScroll);
83	      window.removeEventListener("resize", onScroll);
84	      if (raf) cancelAnimationFrame(raf);
85	    };
86	  }, []);
87	  return { ref, p };
88	}
