90	/* ── scroll-spy: which section id is currently in view ───────────────────── */
91	function useScrollSpy(ids: string[]) {
92	  const [active, setActive] = useState(ids[0] ?? "");
93	  useEffect(() => {
94	    if (typeof IntersectionObserver === "undefined") return;
95	    const seen = new Map<string, number>();
96	    const io = new IntersectionObserver(
97	      (entries) => {
98	        for (const e of entries) seen.set(e.target.id, e.intersectionRatio);
99	        let best = "";
100	        let bestRatio = -1;
101	        for (const [id, ratio] of seen) {
102	          if (ratio > bestRatio) {
103	            best = id;
104	            bestRatio = ratio;
105	          }
106	        }
107	        if (best && bestRatio > 0) setActive(best);
108	      },
109	      { rootMargin: "-20% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
110	    );
111	    for (const id of ids) {
112	      const el = document.getElementById(id);
113	      if (el) io.observe(el);
114	    }
115	    return () => io.disconnect();
116	  }, [ids]);
117	  return active;
118	}
