18	/** A single published post by slug, or null (drives notFound() on the page). */
19	export function getPublishedPost(slug: string): Promise<BlogPost | null> {
20	  return db.blogPost.findFirst({ where: { slug, published: true } });
21	}
22	
23	/**
24	 * Full-text-ish search over published posts. Case-insensitive `contains` across
25	 * title / excerpt / body, plus an exact tag match. Empty query falls back to the
26	 * normal newest-first listing. Runs server-side so results are crawlable.
27	 */
28	export function searchPublishedPosts(q: string): Promise<BlogPost[]> {
29	  const query = q.trim();
30	  if (!query) return getPublishedPosts();
31	  return db.blogPost.findMany({
32	    where: {
33	      published: true,
34	      OR: [
35	        { title: { contains: query, mode: "insensitive" } },
36	        { excerpt: { contains: query, mode: "insensitive" } },
37	        { body: { contains: query, mode: "insensitive" } },
38	        { category: { contains: query, mode: "insensitive" } },
39	        { tags: { has: query.toLowerCase() } },
40	      ],
41	    },
42	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
43	  });
44	}
45	
46	/**
47	 * Up to `limit` other published posts related to `post` — same category first,
48	 * back-filled with the newest posts so the block is never short. The current
49	 * post is always excluded. Drives the "Related articles" internal-linking block
50	 * on the post page (the biggest lever for getting thin/orphaned posts indexed).
51	 */
52	export async function getRelatedPosts(post: BlogPost, limit = 3): Promise<BlogPost[]> {
53	  const sameCategory = await db.blogPost.findMany({
54	    where: { published: true, category: post.category, id: { not: post.id } },
55	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
56	    take: limit,
57	  });
58	  if (sameCategory.length >= limit) return sameCategory;
59	
60	  // Back-fill with the newest posts, skipping anything already picked.
61	  const have = new Set([post.id, ...sameCategory.map((p) => p.id)]);
62	  const recent = await db.blogPost.findMany({
63	    where: { published: true, id: { notIn: [...have] } },
64	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
65	    take: limit - sameCategory.length,
66	  });
67	  return [...sameCategory, ...recent];
68	}
