126	export function formatDate(d: Date | string | null | undefined): string {
127	  if (!d) return "";
128	  const date = typeof d === "string" ? new Date(d) : d;
129	  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
