180	/** Inline markdown for a single run of text. */
181	function inline(text: string): string {
182	  const codes: string[] = [];
183	  // Protect inline code first.
184	  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
185	    codes.push(c);
186	    return `${S0}${codes.length - 1}${S1}`;
187	  });
188	  // Bold.
189	  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
190	  // Inline images ![alt](url) — MUST run before links (they share `[..](..)`).
191	  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
192	    const safe = safeSrc(u);
193	    if (!safe) return "";
194	    return `<img class="${CLS.img} my-6" src="${safe}" alt="${alt}" loading="lazy" />`;
195	  });
196	  // Links [text](url) — only http(s), root-relative, or anchors are allowed.
197	  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
198	    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
199	    const ext = safe.startsWith("http");
200	    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
201	  });
202	  // Restore inline code.
203	  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
204	  return s;
205	}
