207	export function renderMarkdown(md: string): string {
208	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
209	  const out: string[] = [];
210	  let i = 0;
211	
212	  while (i < lines.length) {
213	    const line = lines[i];
214	
215	    // Blank line — skip.
216	    if (!line.trim()) { i++; continue; }
217	
218	    // Horizontal rule.
219	    if (/^---+$/.test(line.trim())) {
220	      out.push('<hr class="my-8 border-white/[0.08]" />');
221	      i++;
222	      continue;
223	    }
224	
225	    // Standalone image line → captioned figure (not wrapped in a paragraph).
226	    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
227	    if (img) {
228	      const safe = safeSrc(img[2]);
229	      if (safe) {
230	        const alt = esc(img[1]);
231	        out.push(
232	          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
233	            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
234	            `</figure>`,
235	        );
236	        i++;
237	        continue;
238	      }
239	    }
240	
241	    // Fenced code block.
242	    if (/^```/.test(line.trim())) {
243	      const buf: string[] = [];
244	      i++;
245	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
246	      i++; // closing fence
247	      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
248	      continue;
249	    }
250	
251	    // Headings.
252	    if (/^###\s+/.test(line)) { out.push(`<h3 class="${CLS.h3}">${inline(line.replace(/^###\s+/, ""))}</h3>`); i++; continue; }
253	    if (/^##\s+/.test(line))  { out.push(`<h2 class="${CLS.h2}">${inline(line.replace(/^##\s+/, ""))}</h2>`);  i++; continue; }
254	    if (/^#\s+/.test(line))   { out.push(`<h1 class="${CLS.h1}">${inline(line.replace(/^#\s+/, ""))}</h1>`);   i++; continue; }
255	
256	    // Ordered list.
257	    if (/^\s*\d+\.\s+/.test(line)) {
258	      const items: string[] = [];
259	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
260	        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
261	        i++;
262	      }
263	      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
264	      continue;
265	    }
266	
267	    // Unordered list.
268	    if (/^\s*[-*]\s+/.test(line)) {
269	      const items: string[] = [];
270	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
271	        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
272	        i++;
273	      }
274	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
275	      continue;
276	    }
277	
278	    // Paragraph — gather until a blank line or block boundary.
279	    const para = [line];
280	    i++;
281	    while (
282	      i < lines.length &&
283	      lines[i].trim() &&
284	      !/^#{1,3}\s/.test(lines[i]) &&
285	      !/^\s*[-*]\s+/.test(lines[i]) &&
286	      !/^\s*\d+\.\s+/.test(lines[i]) &&
287	      !/^```/.test(lines[i].trim()) &&
288	      !/^---+$/.test(lines[i].trim())
289	    ) {
290	      para.push(lines[i]);
291	      i++;
292	    }
293	    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
294	  }
295	
296	  return out.join("\n");
297	}
