/* ----------------------------------------------------------------------------
 * Article-aware renderer for the editorial blog template.
 *
 * Same block/inline grammar as renderMarkdown, but additionally:
 *   • gives every heading a stable, unique `id` so the sticky table-of-contents
 *     spine + scroll-spy can anchor to it,
 *   • returns the H2/H3 outline as a TOC, and
 *   • extracts any question-style heading (text ending in "?") + its following
 *     prose as an FAQ pair, for FAQ JSON-LD.
 *
 * Kept separate from renderMarkdown so the four other callers (admin docs,
 * announcements, what's-new) are completely untouched.
 * ------------------------------------------------------------------------- */

export type TocEntry = { id: string; label: string; level: 2 | 3 };
export type FaqEntry = { q: string; a: string };
export type RenderedArticle = { html: string; toc: TocEntry[]; faq: FaqEntry[] };

/** URL-safe, human-readable heading anchor. */
export function slugifyHeading(text: string): string {
  return (
    text
      .toLowerCase()
      .replace(/`[^`]*`/g, "")
      .replace(/[*_[\]()#]/g, "")
      .replace(/&[a-z]+;/g, "")
      .replace(/[^a-z0-9\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-")
      .slice(0, 60)
      .replace(/^-+|-+$/g, "") || "section"
  );
}

/** Strip inline markdown down to plain text (for FAQ answers / meta). */
function plainInline(text: string): string {
  return text
    .replace(/`([^`]+)`/g, "$1")
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .trim();
}

/** First non-empty prose paragraph of a markdown body, as plain text. */
export function firstParagraph(md: string): string {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const buf: string[] = [];
  for (const line of lines) {
    const t = line.trim();
    if (!t) {
      if (buf.length) break;
      continue;
    }
    if (/^(#{1,3}\s|[-*]\s|\d+\.\s|```|---+$|!\[)/.test(t)) {
      if (buf.length) break;
      continue;
    }
    buf.push(t);
  }
  return plainInline(buf.join(" "));
}

