export function renderArticle(md: string): RenderedArticle {
  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  const toc: TocEntry[] = [];
  const faq: FaqEntry[] = [];
  const usedIds = new Set<string>();
  // A question-style heading whose following prose is still being collected.
  let pendingQ: { q: string; ans: string[] } | null = null;
  let i = 0;

  const uniqueId = (base: string): string => {
    let id = base;
    let n = 2;
    while (usedIds.has(id)) id = `${base}-${n++}`;
    usedIds.add(id);
    return id;
  };
  const flushFaq = () => {
    if (pendingQ) {
      const a = pendingQ.ans.join(" ").replace(/\s+/g, " ").trim();
      if (a && faq.length < 12) faq.push({ q: pendingQ.q, a });
      pendingQ = null;
    }
  };
  const collect = (text: string) => {
    if (pendingQ) pendingQ.ans.push(text);
  };

  while (i < lines.length) {
    const line = lines[i];

    if (!line.trim()) { i++; continue; }

    if (/^---+$/.test(line.trim())) {
      out.push('<hr class="my-8 border-white/[0.08]" />');
      i++;
      continue;
    }

    // Standalone image → captioned figure.
    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
    if (img) {
      const safe = safeSrc(img[2]);
      if (safe) {
        const alt = esc(img[1]);
        out.push(
          `<figure class="my-7"><img class="${CLS.img}" src="${safe}" alt="${alt}" loading="lazy" />` +
            (alt ? `<figcaption class="mt-2 text-center text-xs text-slate-500">${alt}</figcaption>` : "") +
            `</figure>`,
        );
        i++;
        continue;
      }
    }

    // Fenced code block.
    if (/^```/.test(line.trim())) {
      const buf: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
      i++;
      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
      continue;
    }

    // Headings — anchor id + outline/FAQ capture.
    const hMatch = line.match(/^(#{1,3})\s+(.*)$/);
    if (hMatch) {
      flushFaq();
      const level = hMatch[1].length as 1 | 2 | 3;
      const raw = hMatch[2];
      const text = plainInline(raw);
      const id = uniqueId(slugifyHeading(text));
      const cls = level === 1 ? CLS.h1 : level === 2 ? CLS.h2 : CLS.h3;
      out.push(`<h${level} id="${id}" class="${cls} scroll-mt-28">${inline(raw)}</h${level}>`);
      if (level === 2 || level === 3) toc.push({ id, label: text, level });
      if (text.endsWith("?")) pendingQ = { q: text, ans: [] };
      i++;
      continue;
    }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i++;
      }
      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
      collect(items.map(plainInline).join(". "));
      continue;
    }

    // Unordered list.
    if (/^\s*[-*]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
        i++;
      }
      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
      collect(items.map(plainInline).join(". "));
      continue;
    }

    // Paragraph.
    const para = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() &&
      !/^#{1,3}\s/.test(lines[i]) &&
      !/^\s*[-*]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^```/.test(lines[i].trim()) &&
      !/^---+$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i++;
    }
    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
    collect(plainInline(para.join(" ")));
  }

  flushFaq();
  return { html: out.join("\n"), toc, faq };
}

/* ----------------------------------------------------------------------------
 * Presentation helpers for the editorial post template.
 * ------------------------------------------------------------------------- */

/** 1–2 letter monogram for the byline avatar. */
export function authorInitials(name: string): string {
  const parts = (name || "Nxeon").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "N";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

/**
 * A stable, on-brand accent colour for a post — keyed off the product line the
 * post funnels to, so game guides, hosting guides and domain guides each read a
 * little differently while staying inside Nxeon's navy/violet/cyan family.
 */
export function accentForPost(post: Pick<BlogPost, "category" | "tags" | "title">): string {
  const { href } = productLinkForPost(post as BlogPost);
  const map: Record<string, string> = {
    "/game-servers": "#8b5cf6", // violet
    "/web-hosting": "#3b82f6", // blue
    "/domains": "#22d3ee", // cyan
    "/business-email": "#38bdf8", // sky
    "/vps": "#6f47f5", // brand violet
  };
  return map[href] ?? "#6f47f5";
}

/** Icon name (see components/marketing/icons) that best fits a post's topic. */
export function iconForPost(post: Pick<BlogPost, "category" | "tags" | "title">): string {
  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));
  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "server hosting", "modpack")) return "game";
  if (has("dns", "domain", "nameserver", "whois", "record")) return "globe";
  if (has("email", "mail", "smtp", "spf", "dkim", "imap")) return "mail";
  if (has("security", "firewall", "ssh", "ssl", "vpn", "hardening", "fail2ban", "port")) return "shield";
  if (has("backup", "snapshot", "restore")) return "backup";
  if (has("docker", "linux", "terminal", "command", "cli", "systemd", "bash")) return "terminal";
  if (has("performance", "monitor", "ram", "cpu", "benchmark", "speed", "tune")) return "gauge";
  if (has("web hosting", "wordpress", "website", "php", "nginx")) return "apps";
  if (has("price", "pricing", "cost", "cheap", "compare", "vs", "plan")) return "scale";
  return "server";
}

