"use client";

/**
 * BlogPostView — the editorial article shell for REAL blog posts.
 *
 * This is the production sibling of the preview-only BlogArticle.tsx: it wears
 * the same design language (art/gradient banner hero, byline + reading time, a
 * sticky table-of-contents "spine" that fills with reading progress and
 * scroll-spies the active section, a slim top progress bar, a GEO "quick answer"
 * box, styled long-form body, product CTA rails and a related-posts strip) but
 * every value is driven by plain, serialisable props derived from a BlogPost
 * row in app/blog/[slug]/page.tsx. It degrades gracefully when a post has no
 * cover image (gradient + topic icon) or no TOC-able headings (full-width body,
 * no spine). All iconography comes from components/marketing/icons — no emoji.
 */

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion, StarRow } from "@/components/marketing/gamelanding/kit";
import {
  IconBolt,
  IconArrow,
  IconClock,
  IconGame,
  IconGlobe,
  IconMail,
  IconShield,
  IconBackup,
  IconTerminal,
  IconGauge,
  IconApps,
  IconScale,
  IconServer,
  IconSpark,
} from "@/components/marketing/icons";

const ICONS: Record<string, (p: { size?: number; className?: string }) => React.ReactElement> = {
  game: IconGame,
  globe: IconGlobe,
  mail: IconMail,
  shield: IconShield,
  backup: IconBackup,
  terminal: IconTerminal,
  gauge: IconGauge,
  apps: IconApps,
  scale: IconScale,
  server: IconServer,
};
function iconFor(name: string) {
  return ICONS[name] ?? IconServer;
}

export type TocItem = { id: string; label: string; level: 2 | 3 };
export type QuickFact = { label: string; value: string };
export type RelatedItem = {
  slug: string;
  title: string;
  category: string;
  readMins: number;
  coverImage: string | null;
  iconName: string;
};
export type ProductLink = { label: string; href: string; blurb: string };

export type BlogPostViewProps = {
  title: string;
  deck: string;
  category: string;
  author: string;
  authorInitials: string;
  dateLabel: string;
  updatedLabel: string | null;
  readingLabel: string;
  accent: string;
  coverImage: string | null;
  iconName: string;
  tags: string[];
  contentHtml: string;
  toc: TocItem[];
  quickAnswer: { answer: string; facts: QuickFact[] } | null;
  product: ProductLink;
  related: RelatedItem[];
};

/* ── reading progress (0→1) across the article body ──────────────────────── */
function useReadingProgress<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [p, setP] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    const compute = () => {
      raf = 0;
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      const total = r.height - vh;
      const travelled = -r.top;
      setP(total <= 0 ? 1 : Math.max(0, Math.min(1, travelled / total)));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(compute);
    };
    compute();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);
  return { ref, p };
}

/* ── scroll-spy: which section id is currently in view ───────────────────── */
function useScrollSpy(ids: string[]) {
  const [active, setActive] = useState(ids[0] ?? "");
  useEffect(() => {
    if (typeof IntersectionObserver === "undefined" || ids.length === 0) return;
    const seen = new Map<string, number>();
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) seen.set(e.target.id, e.intersectionRatio);
        let best = "";
        let bestRatio = -1;
        for (const [id, ratio] of seen) {
          if (ratio > bestRatio) {
            best = id;
            bestRatio = ratio;
          }
        }
        if (best && bestRatio > 0) setActive(best);
      },
      { rootMargin: "-20% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );
    for (const id of ids) {
      const el = document.getElementById(id);
      if (el) io.observe(el);
    }
    return () => io.disconnect();
  }, [ids]);
  return active;
}

export function BlogPostView(props: BlogPostViewProps) {
  const {
    title,
    deck,
    category,
    author,
    authorInitials,
    dateLabel,
    updatedLabel,
    readingLabel,
    accent,
    coverImage,
    iconName,
    tags,
    contentHtml,
    toc,
    quickAnswer,
    product,
    related,
  } = props;

  const reduced = usePrefersReducedMotion();
  const [imgOk, setImgOk] = useState(true);
  const { ref: bodyRef, p } = useReadingProgress<HTMLDivElement>();
  const ids = toc.map((t) => t.id);
  const active = useScrollSpy(ids);
  const HeroIcon = iconFor(iconName);
  const hasCover = Boolean(coverImage) && imgOk;
  const hasToc = toc.length >= 2;

  return (
    <div className="relative">
      {/* slim top reading-progress bar */}
      <div className="fixed inset-x-0 top-0 z-[70] h-[3px] bg-transparent" aria-hidden>
        <div
          className="h-full origin-left"
          style={{
            width: `${p * 100}%`,
            background: `linear-gradient(90deg, ${accent}, #3b82f6, #22d3ee)`,
            boxShadow: `0 0 12px ${accent}88`,
          }}
        />
      </div>

      {/* ── BANNER HERO ──────────────────────────────────────────────────── */}
      <header className="relative overflow-hidden">
        <div className="absolute inset-0 -z-10">
          {hasCover ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={coverImage as string}
              alt=""
              onError={() => setImgOk(false)}
              className={`h-full w-full object-cover object-center ${reduced ? "" : "pv-kenburns"}`}
            />
          ) : (
            <div className="hero-aura absolute inset-0" />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/85 to-navy-950/55" />
          <div
            className="absolute inset-0"
            style={{ background: `radial-gradient(70% 60% at 20% 100%, ${accent}22, transparent 65%)` }}
          />
        </div>

        <div className="rail flex min-h-[52vh] flex-col justify-end pb-12 pt-28 sm:min-h-[58vh]">
          <div className="max-w-3xl">
            <div className="mb-5">
              <Link href="/blog" className="inline-flex items-center gap-1.5 text-sm text-slate-300 transition-colors hover:text-white">
                <IconArrow size={15} className="rotate-180" /> All guides
              </Link>
            </div>
            <div className="flex items-center gap-3">
              <span
                className="flex h-9 w-9 items-center justify-center rounded-lg border"
                style={{ borderColor: `${accent}33`, background: `${accent}18`, color: accent }}
              >
                <HeroIcon size={18} />
              </span>
              <span className="eyebrow" style={{ color: accent }}>
                {category}
              </span>
            </div>
            <h1 className="mt-5 text-3xl font-black leading-[1.08] tracking-tight text-white sm:text-4xl lg:text-[3rem]">
              {title}
            </h1>
            {deck && <p className="mt-5 max-w-2xl text-lg leading-relaxed text-slate-200/90">{deck}</p>}

            {/* byline row */}
            <div className="mt-7 flex flex-wrap items-center gap-x-5 gap-y-3 text-sm text-slate-300">
              <span className="flex items-center gap-2.5">
                <span
                  className="flex h-9 w-9 items-center justify-center rounded-full text-xs font-semibold text-white"
                  style={{ background: `linear-gradient(135deg, ${accent}, #3b82f6)` }}
                >
                  {authorInitials}
                </span>
                <span>
                  <span className="block font-semibold text-white">{author}</span>
                  <span className="block text-xs text-slate-400">Nxeon editorial</span>
                </span>
              </span>
              <span className="hidden h-8 w-px bg-white/15 sm:block" />
              <span className="text-slate-400">{dateLabel}</span>
              <span className="inline-flex items-center gap-1.5 text-slate-400">
                <IconClock size={15} /> {readingLabel}
              </span>
              {updatedLabel && (
                <span
                  className="inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-medium"
                  style={{ borderColor: `${accent}44`, color: "#e2e8f0", background: `${accent}14` }}
                >
                  {updatedLabel}
                </span>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* ── BODY: sticky TOC spine + article ─────────────────────────────── */}
      <div ref={bodyRef} className={`rail grid gap-10 py-14 ${hasToc ? "lg:grid-cols-12 lg:gap-14" : ""}`}>
        {/* TOC SPINE (sticky, desktop) — only when there are enough headings */}
        {hasToc && (
          <aside className="hidden lg:col-span-3 lg:block">
            <div className="sticky top-24">
              <p className="section-label mb-4">On this page</p>
              <nav className="relative pl-5">
                <div className="absolute bottom-1 left-[3px] top-1 w-px bg-white/10" aria-hidden />
                <div
                  className="absolute left-[3px] top-1 w-px"
                  style={{
                    height: `calc(${(reduced ? 1 : p) * 100}% - 8px)`,
                    maxHeight: "calc(100% - 8px)",
                    background: `linear-gradient(to bottom, ${accent}, #3b82f6)`,
                    transition: reduced ? "none" : "height 0.15s linear",
                  }}
                  aria-hidden
                />
                <ul className="space-y-3.5">
                  {toc.map((t) => {
                    const on = active === t.id;
                    return (
                      <li key={t.id} className={`relative ${t.level === 3 ? "pl-3" : ""}`}>
                        <span
                          className="absolute -left-[18px] top-1.5 h-2 w-2 rounded-full ring-4 ring-navy-950 transition-colors"
                          style={{ background: on ? accent : "rgba(255,255,255,0.2)" }}
                          aria-hidden
                        />
                        <a
                          href={`#${t.id}`}
                          className={`block text-sm transition-colors ${on ? "font-semibold text-white" : "text-slate-400 hover:text-slate-200"}`}
                        >
                          {t.label}
                        </a>
                      </li>
                    );
                  })}
                </ul>
              </nav>

              {/* mini product nudge under TOC */}
              <div className="mt-8 rounded-2xl border border-white/[0.08] bg-navy-900/50 p-4">
                <p className="text-xs leading-relaxed text-slate-400">{product.blurb}</p>
                <Link href={product.href} className="btn-deploy mt-3 w-full px-4 py-2.5 text-sm">
                  {product.label} <span className="dep-arrow" aria-hidden>→</span>
                </Link>
              </div>
            </div>
          </aside>
        )}

        {/* ARTICLE */}
        <article className={hasToc ? "lg:col-span-9" : ""}>
          <div className={`mx-auto max-w-2xl ${hasToc ? "lg:mx-0" : ""}`}>
            {/* QUICK ANSWER (GEO box) */}
            {quickAnswer && (
              <section id="quick-answer" className="scroll-mt-28">
                <div
                  className="relative overflow-hidden rounded-2xl border p-6 sm:p-7"
                  style={{
                    borderColor: `${accent}44`,
                    background: "linear-gradient(180deg, rgba(13,21,38,0.9), rgba(10,16,31,0.7))",
                    boxShadow: `0 20px 60px -34px ${accent}88`,
                  }}
                >
                  <div
                    className="pointer-events-none absolute -right-16 -top-16 h-40 w-40 rounded-full blur-3xl"
                    style={{ background: `${accent}30` }}
                    aria-hidden
                  />
                  <div className="flex items-center gap-2">
                    <span className="flex h-7 w-7 items-center justify-center rounded-lg" style={{ background: `${accent}22`, color: accent }}>
                      <IconBolt size={16} />
                    </span>
                    <span className="text-[12px] font-semibold uppercase tracking-[0.16em]" style={{ color: accent }}>
                      Quick answer
                    </span>
                  </div>
                  <p className="mt-4 text-lg font-medium leading-relaxed text-white">{quickAnswer.answer}</p>
                  {quickAnswer.facts.length > 0 && (
                    <div className="mt-5 grid gap-px overflow-hidden rounded-xl border border-white/[0.07] bg-white/[0.05] sm:grid-cols-2">
                      {quickAnswer.facts.map((f) => (
                        <div key={f.label} className="bg-navy-900/70 px-4 py-3">
                          <div className="text-[11px] uppercase tracking-wide text-slate-500">{f.label}</div>
                          <div className="mt-0.5 text-sm font-semibold text-white">{f.value}</div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </section>
            )}

            {/* BODY */}
            <div
              className={`${quickAnswer ? "mt-10" : ""} text-[17px] leading-[1.75] text-slate-300`}
              dangerouslySetInnerHTML={{ __html: contentHtml }}
            />

            {/* MID / PRIMARY PRODUCT RAIL */}
            <ProductRail accent={accent} coverImage={hasCover ? (coverImage as string) : null} product={product} className="mt-14" />

            {/* TAGS */}
            {tags.length > 0 && (
              <div className="mt-10 flex flex-wrap gap-2 border-t border-white/[0.08] pt-6">
                {tags.map((t) => (
                  <span key={t} className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-400">
                    #{t}
                  </span>
                ))}
              </div>
            )}

            {/* AUTHOR CARD */}
            <div className="mt-10 flex items-center gap-4 rounded-2xl border border-white/[0.08] bg-navy-900/50 p-5">
              <span
                className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full text-sm font-semibold text-white"
                style={{ background: `linear-gradient(135deg, ${accent}, #3b82f6)` }}
              >
                {authorInitials}
              </span>
              <div>
                <p className="text-sm font-semibold text-white">
                  {author} · <span className="font-normal text-slate-400">Nxeon editorial</span>
                </p>
                <p className="mt-1 flex items-center gap-2 text-sm text-slate-400">
                  <StarRow rating={5} size="text-xs" /> Straight-talking guides from the team that runs the servers.
                </p>
              </div>
            </div>
          </div>
        </article>
      </div>

      {/* ── RELATED POSTS ────────────────────────────────────────────────── */}
      {related.length > 0 && (
        <section className="tone-panel py-16">
          <div className="rail">
            <div className="flex items-end justify-between gap-4">
              <div>
                <span className="eyebrow">Keep reading</span>
                <h2 className="mt-2 text-2xl font-bold tracking-tight text-white sm:text-3xl">Related guides</h2>
              </div>
              <Link href="/blog" className="hidden shrink-0 items-center gap-1.5 text-sm font-semibold text-brand-300 hover:text-brand-200 sm:inline-flex">
                All guides <IconArrow size={15} />
              </Link>
            </div>
            <div className="mt-8 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
              {related.map((r) => {
                const RIcon = iconFor(r.iconName);
                return (
                  <Link key={r.slug} href={`/blog/${r.slug}`} className="card card-hover group flex flex-col overflow-hidden !p-0">
                    <div className="relative aspect-[16/10] overflow-hidden">
                      {r.coverImage ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={r.coverImage}
                          alt=""
                          loading="lazy"
                          className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                        />
                      ) : (
                        <div className="hero-aura flex h-full w-full items-center justify-center bg-navy-900">
                          <RIcon size={34} className="text-brand-300/70" />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/20 to-transparent" />
                      <span className="absolute left-3 top-3 rounded-full border border-white/15 bg-navy-950/60 px-2.5 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-200 backdrop-blur-md">
                        {r.category}
                      </span>
                    </div>
                    <div className="flex flex-1 flex-col p-4">
                      <h3 className="text-sm font-semibold leading-snug text-white group-hover:text-brand-200">{r.title}</h3>
                      <span className="mt-3 inline-flex items-center gap-1.5 text-xs text-slate-500">
                        <IconClock size={13} /> {r.readMins} min read
                      </span>
                    </div>
                  </Link>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* ── END CTA ──────────────────────────────────────────────────────── */}
      <section className="tone-deep py-20">
        <div className="rail">
          <ProductRail accent={accent} coverImage={hasCover ? (coverImage as string) : null} product={product} big />
        </div>
      </section>
    </div>
  );
}

/* ── product CTA rail ────────────────────────────────────────────────────── */
function ProductRail({
  accent,
  coverImage,
  product,
  big = false,
  className = "",
}: {
  accent: string;
  coverImage: string | null;
  product: ProductLink;
  big?: boolean;
  className?: string;
}) {
  return (
    <div
      className={`relative overflow-hidden rounded-3xl border ${className}`}
      style={{
        borderColor: `${accent}44`,
        background: "linear-gradient(120deg, rgba(10,16,31,0.9), rgba(13,21,38,0.75))",
      }}
    >
      {coverImage && (
        <div className="absolute inset-0 -z-10 opacity-30">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={coverImage} alt="" className="h-full w-full object-cover" />
          <div className="absolute inset-0 bg-gradient-to-r from-navy-950 via-navy-950/85 to-navy-950/60" />
        </div>
      )}
      <div
