import Link from "next/link";
import type { Metadata } from "next";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { Reveal } from "@/components/marketing/Reveal";
import { CtaBand } from "@/components/marketing/sections";
import {
  IconGame,
  IconGlobe,
  IconMail,
  IconShield,
  IconBackup,
  IconTerminal,
  IconGauge,
  IconApps,
  IconScale,
  IconServer,
  IconArrow,
} from "@/components/marketing/icons";
import { getPostsPage, iconForPost, formatDate, readMinutes, APP_URL } from "@/lib/blog";

export const dynamic = "force-dynamic";

const ICONS: Record<string, (p: { size?: number; className?: string }) => React.ReactElement> = {
  game: IconGame,
  globe: IconGlobe,
  mail: IconMail,
  shield: IconShield,
  backup: IconBackup,
  terminal: IconTerminal,
  gauge: IconGauge,
  apps: IconApps,
  scale: IconScale,
  server: IconServer,
};

type Search = { q?: string; page?: string };

function parsePage(v?: string): number {
  const n = Number.parseInt(v ?? "1", 10);
  return Number.isFinite(n) && n > 0 ? n : 1;
}

/** Build a /blog URL preserving the search query and page number. */
function pageHref(page: number, q: string): string {
  const params = new URLSearchParams();
  if (q) params.set("q", q);
  if (page > 1) params.set("page", String(page));
  const qs = params.toString();
  return qs ? `/blog?${qs}` : "/blog";
}

export async function generateMetadata({ searchParams }: { searchParams: Promise<Search> }): Promise<Metadata> {
  const { q, page: pageRaw } = await searchParams;
  const query = (q ?? "").trim();
  const page = parsePage(pageRaw);
  const suffix = page > 1 ? ` — page ${page}` : "";
  const title = `Blog — VPS & self-hosting guides${suffix}`;
  const description =
    "Practical guides on running a VPS: Minecraft and game servers, Linux security, pointing domains, and choosing the right hosting for your project.";
  // Per-page self-canonical. Search result listings are not canonical targets —
  // point them back at the clean index so thin/duplicate query pages don't index.
  const canonical = query ? "/blog" : pageHref(page, "");
  return {
    title,
    description,
    alternates: { canonical },
    ...(query ? { robots: { index: false, follow: true } } : {}),
    openGraph: {
      type: "website",
      title: `Nxeon Blog — VPS & self-hosting guides${suffix}`,
      description,
      url: `${APP_URL}${canonical}`,
    },
  };
}

/** Cover for a card: real image if present, else a gradient + topic icon block. */
function CardCover({
  coverImage,
  iconName,
  className,
  iconSize = 30,
}: {
  coverImage: string | null;
  iconName: string;
  className: string;
  iconSize?: number;
}) {
  const Icon = ICONS[iconName] ?? IconServer;
  if (coverImage) {
    return (
      <div className={`overflow-hidden ${className}`}>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={coverImage} alt="" loading="lazy" className="h-full w-full object-cover" />
      </div>
    );
  }
  return (
    <div className={`hero-aura flex items-center justify-center bg-navy-900 ${className}`}>
      <Icon size={iconSize} className="text-brand-300/70" />
    </div>
  );
}

/** Compact, windowed numeric pager with prev/next. */
function Pager({ page, totalPages, q }: { page: number; totalPages: number; q: string }) {
  if (totalPages <= 1) return null;
  const window: number[] = [];
  const from = Math.max(1, page - 2);
  const to = Math.min(totalPages, page + 2);
  for (let i = from; i <= to; i++) window.push(i);

  const linkCls =
    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.04] px-3 text-sm font-medium text-slate-300 transition-colors hover:border-brand-400/50 hover:text-white";
  const disabledCls =
    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 text-sm font-medium text-slate-600 cursor-not-allowed";

  return (
    <nav className="mt-14 flex flex-wrap items-center justify-center gap-2" aria-label="Blog pagination">
      {page > 1 ? (
        <Link href={pageHref(page - 1, q)} rel="prev" className={linkCls} aria-label="Previous page">
          <IconArrow size={15} className="rotate-180" /> Prev
        </Link>
      ) : (
        <span className={disabledCls} aria-hidden>
          <IconArrow size={15} className="rotate-180" /> Prev
        </span>
      )}

      {from > 1 && (
        <>
          <Link href={pageHref(1, q)} className={linkCls}>
            1
          </Link>
          {from > 2 && <span className="px-1 text-slate-600">…</span>}
        </>
      )}

      {window.map((n) =>
        n === page ? (
          <span
            key={n}
            aria-current="page"
            className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-200"
          >
            {n}
          </span>
        ) : (
          <Link key={n} href={pageHref(n, q)} className={linkCls}>
            {n}
          </Link>
        ),
      )}

      {to < totalPages && (
        <>
          {to < totalPages - 1 && <span className="px-1 text-slate-600">…</span>}
          <Link href={pageHref(totalPages, q)} className={linkCls}>
            {totalPages}
          </Link>
        </>
      )}

      {page < totalPages ? (
        <Link href={pageHref(page + 1, q)} rel="next" className={linkCls} aria-label="Next page">
          Next <IconArrow size={15} />
        </Link>
      ) : (
        <span className={disabledCls} aria-hidden>
          Next <IconArrow size={15} />
        </span>
      )}
    </nav>
  );
}

export default async function BlogIndex({ searchParams }: { searchParams: Promise<Search> }) {
  const { q, page: pageRaw } = await searchParams;
  const query = (q ?? "").trim();
  const requestedPage = parsePage(pageRaw);
  const { posts, total, page, totalPages } = await getPostsPage({ page: requestedPage, q: query });
  const searching = query.length > 0;

  // Feature the newest post only on page 1 of the default (non-search) view.
  const showFeatured = !searching && page === 1;
  const featured = showFeatured ? posts[0] : undefined;
  const grid = showFeatured ? posts.slice(1) : posts;

  return (
    <div className="flex min-h-screen flex-col">
      {/* rel prev/next — hoisted into <head> by React 19. Google-legacy but still
          a positive crawl signal for a long paginated series. */}
      {page > 1 && <link rel="prev" href={`${APP_URL}${pageHref(page - 1, query)}`} />}
      {page < totalPages && <link rel="next" href={`${APP_URL}${pageHref(page + 1, query)}`} />}

      <MarketingHeader />
      <main className="flex-1">
        {/* Hero */}
        <section className="relative overflow-hidden">
          <div
            className="pointer-events-none absolute inset-x-0 top-0 h-[380px] opacity-70"
            style={{ backgroundImage: "radial-gradient(ellipse 60% 50% at 50% 0%, rgba(111,71,245,0.16), transparent)" }}
          />
          <div className="relative mx-auto max-w-6xl px-5 py-20 text-center sm:px-6">
            <Reveal>
              <p className="section-label mb-3">The Nxeon Blog</p>
              <h1 className="text-4xl font-extrabold tracking-tight sm:text-5xl">
                Guides for people who <span className="grad-text">run their own servers</span>
              </h1>
              <p className="mx-auto mt-5 max-w-2xl text-lg text-slate-400">
                Straight-talking tutorials and comparisons on VPS hosting, game servers, Linux
                security, and domains — no fluff, just what actually works.
              </p>

              {/* Search */}
              <form method="get" action="/blog" role="search" className="mx-auto mt-8 flex max-w-xl items-center gap-2">
                <div className="relative flex-1">
                  <svg
                    aria-hidden
                    viewBox="0 0 24 24"
                    fill="none"
                    className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-500"
                  >
                    <circle cx="11" cy="11" r="7" stroke="currentColor" strokeWidth="2" />
                    <path d="m20 20-3-3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
                  </svg>
                  <input
                    type="search"
                    name="q"
                    defaultValue={query}
                    placeholder="Search guides — e.g. minecraft, ssh, dns…"
                    aria-label="Search the blog"
                    className="w-full rounded-xl border border-white/10 bg-white/[0.04] py-3 pl-10 pr-4 text-sm text-white placeholder:text-slate-500 outline-none transition-colors focus:border-brand-400/60 focus:bg-white/[0.06]"
                  />
                </div>
                <button
                  type="submit"
                  className="rounded-xl border border-brand-500/40 bg-brand-500/15 px-5 py-3 text-sm font-semibold text-brand-200 transition-colors hover:bg-brand-500/25"
                >
                  Search
                </button>
              </form>
            </Reveal>
          </div>
        </section>

        {/* Posts */}
        <section className="mx-auto max-w-6xl px-5 pb-24 sm:px-6">
          {searching && (
            <div className="mb-8 flex flex-wrap items-center justify-between gap-3">
              <p className="text-sm text-slate-400">
                {total === 0 ? "No results for" : `${total} result${total === 1 ? "" : "s"} for`}{" "}
                <span className="font-semibold text-white">“{query}”</span>
              </p>
              <Link href="/blog" className="inline-flex items-center gap-1.5 text-sm font-medium text-brand-300 hover:text-brand-200">
                Clear search
              </Link>
            </div>
          )}

          {posts.length === 0 ? (
            <div className="card py-16 text-center">
              <p className="text-lg font-semibold text-white">
                {searching ? "Nothing matched your search" : "No posts yet"}
              </p>
              <p className="mt-2 text-sm text-slate-400">
                {searching ? (
                  <>
                    Try a broader term, or{" "}
                    <Link href="/blog" className="text-brand-300 hover:text-brand-200">
                      browse all guides
                    </Link>
                    .
                  </>
                ) : (
                  <>We&apos;re writing the first guides now — check back shortly.</>
                )}
              </p>
            </div>
          ) : (
            <>
              {/* Featured post — only on page 1 of the default view */}
              {featured && (
                <Reveal>
                  <Link
                    href={`/blog/${featured.slug}`}
                    className="card card-hover group flex flex-col gap-6 md:flex-row md:items-center"
                  >
                    <CardCover
                      coverImage={featured.coverImage}
                      iconName={iconForPost(featured)}
                      className="h-40 w-full shrink-0 rounded-2xl border border-white/[0.06] md:h-44 md:w-64"
                      iconSize={44}
                    />
                    <div className="min-w-0">
                      <div className="mb-3 flex flex-wrap items-center gap-2 text-xs text-slate-400">
                        <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2.5 py-0.5 font-medium text-brand-300">
                          {featured.category}
                        </span>
                        <span>{formatDate(featured.publishedAt ?? featured.createdAt)}</span>
                        <span aria-hidden>·</span>
                        <span>{readMinutes(featured.body)} min read</span>
                      </div>
                      <h2 className="text-2xl font-bold tracking-tight text-white transition-colors group-hover:text-brand-200">
                        {featured.title}
                      </h2>
                      <p className="mt-2 line-clamp-3 text-slate-400">{featured.excerpt}</p>
                    </div>
                  </Link>
                </Reveal>
              )}

              {grid.length > 0 && (
                <div className={`grid gap-5 sm:grid-cols-2 lg:grid-cols-3 ${featured ? "mt-6" : ""}`}>
                  {grid.map((post, i) => (
                    <Reveal key={post.id} delay={(i % 3) * 60}>
                      <Link
                        href={`/blog/${post.slug}`}
                        className="card card-hover group flex h-full flex-col overflow-hidden !p-0"
                      >
                        <CardCover
                          coverImage={post.coverImage}
                          iconName={iconForPost(post)}
                          className="aspect-[16/9] w-full border-b border-white/[0.06]"
                        />
                        <div className="flex flex-1 flex-col p-5">
                          <div className="mb-2 flex flex-wrap items-center gap-2 text-[11px] text-slate-500">
                            <span className="rounded-full border border-white/10 bg-white/[0.05] px-2 py-0.5 font-medium text-slate-300">
                              {post.category}
                            </span>
                            <span>{readMinutes(post.body)} min read</span>
                          </div>
                          <h3 className="text-base font-semibold text-white transition-colors group-hover:text-brand-200">
                            {post.title}
                          </h3>
                          <p className="mt-2 line-clamp-3 text-sm leading-relaxed text-slate-400">{post.excerpt}</p>
                          <span className="mt-4 inline-flex items-center gap-1.5 text-xs font-medium text-brand-300">
                            Read more <IconArrow size={13} />
                          </span>
                        </div>
                      </Link>
                    </Reveal>
                  ))}
                </div>
              )}

              <Pager page={page} totalPages={totalPages} q={query} />
            </>
          )}

          <div className="mt-20">
            <CtaBand />
          </div>
        </section>
      </main>
      <MarketingFooter />
    </div>
  );
}

