#!/usr/bin/env node
/**
 * blog-upgrade.mjs — retroactively bring old blog posts up to the new editorial
 * template's expectations. For each targeted post it, idempotently:
 *
 *   1. STRIPS EMOJI from title / excerpt / body / SEO fields (the new renderer
 *      uses line-icons, never emoji — components/marketing/icons.tsx).
 *   2. ENSURES A COVER IMAGE — if the post has no coverImage, assigns the
 *      most topic-relevant screenshot from public/blog/screenshots (same keyword
 *      → image map as scripts/blog-image-backfill.mjs).
 *   3. EMBEDS TOPIC-RELEVANT INLINE IMAGES — replaces any {{SCREENSHOT}}
 *      sentinels, or (if the post has none and no image yet) injects up to
 *      --max-inline distinct screenshots after its headings.
 *
 * IDEMPOTENT: re-running makes no further changes — no emoji left to strip, a
 * cover already set is kept, and posts that already carry a /blog/screenshots
 * image are not re-injected. A post is only written when something actually
 * changed.
 *
 * SAFE BY DEFAULT: this is a DRY RUN unless you pass --apply. Even with --apply
 * it refuses to write unless you also pass --yes (or set ALLOW_APPLY=1), and it
 * prints the target database host first so a prod write is never a surprise.
 * Writing to the production DB is a gated action — run the dry run, review the
 * sample diffs, then have the main session apply it in reviewed batches.
 *
 * USAGE
 *   node scripts/blog-upgrade.mjs                       # dry run, all published posts
 *   node scripts/blog-upgrade.mjs --slug my-post-slug   # dry run, one post
 *   node scripts/blog-upgrade.mjs --tag seobatch        # dry run, the SEO batch
 *   node scripts/blog-upgrade.mjs --limit 50 --samples 5
 *   node scripts/blog-upgrade.mjs --tag seobatch --apply --yes   # WRITE (gated)
 *
 * FLAGS
 *   --slug <slug>     target a single post
 *   --tag <tag>       target posts carrying <tag> (e.g. seobatch)
 *   (default)         all published posts
 *   --limit <n>       cap how many posts are processed (0 = no cap)
 *   --samples <n>     how many before/after examples to print in full (default 3)
 *   --max-inline <n>  max inline images to inject when a post has none (default 2)
 *   --no-inline       skip inline-image injection entirely
 *   --apply           actually write changes (otherwise dry run)
 *   --yes             required alongside --apply to confirm writes
 */

import { db } from "./blog-seed-lib.mjs";

/* ── args ─────────────────────────────────────────────────────────────────── */
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const val = (name, def = null) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] && !args[i + 1].startsWith("--") ? args[i + 1] : def;
};
const SLUG = val("slug");
const TAG = val("tag");
const LIMIT = parseInt(val("limit", "0"), 10) || 0;
const SAMPLES = parseInt(val("samples", "3"), 10);
const MAX_INLINE = has("no-inline") ? 0 : parseInt(val("max-inline", "2"), 10);
const APPLY = has("apply");
const CONFIRM = has("yes") || process.env.ALLOW_APPLY === "1";

/* ── image map (same approach as blog-image-backfill.mjs) ─────────────────── */
const BASE = "/blog/screenshots";
const IMAGES = [
  { f: "game-servers.png", alt: "The Nxeon game-server control panel — live console, player slots, and TPS",
    kw: ["minecraft","rust","valheim","palworld","ark","game server","gmod","garry","fivem","zomboid","terraria","satisfactory","factorio","enshrouded","vrising","v rising","cs2","counter-strike","tf2","team fortress","dayz","squad","mordhau","unturned","teamspeak","mumble","modpack","forge","fabric","plugin","spigot","paper","aikar","geyser","smp","steamcmd","dedicated server","assetto","necesse","vintage story","core keeper","sons of the forest","dont starve","don't starve","7 days","enshroud"] },
  { f: "server-dashboard.png", alt: "The Nxeon control panel showing live CPU, memory, and network metrics for a VPS",
    kw: ["monitor","metric","cpu","ram","memory","performance","htop","netdata","grafana","prometheus","uptime","load","tune","swap","disk space","logs","journalctl"] },
  { f: "dns-manager.png", alt: "Managing DNS records for a domain in the Nxeon control panel",
    kw: ["dns","a record","cname","mx record","ptr","caa","dnssec","nameserver","subdomain","wildcard","point a domain","point your domain","cloudflare","namecheap","godaddy","dig","nslookup","glue record","propagation","records"] },
  { f: "mail-inbox.png", alt: "The business-email inbox in the Nxeon customer portal",
    kw: ["email","spf","dkim","dmarc","mailbox","business email","spam","mx ","google workspace","catch-all","forward","smtp","deliverability","inbox"] },
  { f: "migration-center.png", alt: "The Nxeon migration center showing a completed, verified migration",
    kw: ["migrate","migration","move your website","move a minecraft world","transfer"] },
  { f: "deploy-wizard.png", alt: "Deploying a new server with the Nxeon one-click deploy wizard",
    kw: ["deploy","install","set up","setup","provision","first server","systemd","nginx","apache","caddy","docker","compose","portainer","node.js","nodejs","pm2","next.js","flask","django","fastapi","php","lemp","certbot","ssl","gitea","cron","static","code-server","wordpress","woocommerce","reverse proxy","nextcloud","jellyfin","plex","pi-hole","wireguard","openvpn","vaultwarden","n8n","ghost","immich","home assistant","matrix","mastodon","syncthing","freshrss","navidrome","self-host","discord bot","telegram bot"] },
  { f: "pricing-plans.png", alt: "Nxeon VPS plans and pricing",
    kw: ["best vps","cheap","affordable","price","pricing","cost","plan","how much","vps vs","dedicated","managed","unmanaged","kvm","openvz","choose a vps","compare","alternative","how many players","specs"] },
  { f: "ai-builder.png", alt: "Building a website with Claude AI inside the Nxeon control panel",
    kw: ["ai","claude","build a website with ai","vibe"] },
  { f: "block-storage-volumes.png", alt: "NVMe block-storage volumes in the Nxeon control panel",
    kw: ["block storage","volume","backup","snapshot","nvme"] },
  { f: "domain-generator.png", alt: "Nxeon's AI domain name generator",
    kw: ["domain name","choose a domain","register a domain","domain generator","whois","registrar"] },
  { f: "free-tools.png", alt: "Nxeon's free developer tools",
    kw: ["free tool","port checker","whois","ssl checker","subnet","ports","port"] },
];
const REAL = new Set([
  "game-servers.png","server-dashboard.png","dns-manager.png","mail-inbox.png","migration-center.png",
  "deploy-wizard.png","pricing-plans.png","ai-builder.png","block-storage-volumes.png","domain-generator.png","free-tools.png",
]);
const AVAILABLE = IMAGES.filter((i) => REAL.has(i.f));

/** Rank the available screenshots by relevance to a post (best first). */
function rank(post) {
  const hay = `${post.title} ${(post.tags || []).join(" ")} ${post.category}`.toLowerCase();
  const scored = AVAILABLE.map((img) => ({ img, score: img.kw.reduce((n, k) => n + (hay.includes(k) ? 1 : 0), 0) }));
  scored.sort((a, b) => b.score - a.score);
  if (scored[0].score === 0) {
    const def = AVAILABLE.find((i) => i.f === "deploy-wizard.png");
    return [def, ...AVAILABLE.filter((i) => i !== def)];
  }
  return scored.map((s) => s.img);
}
const imgMd = (img) => `![${img.alt}](${BASE}/${img.f})`;

/* ── emoji stripping ──────────────────────────────────────────────────────── */
// A pictographic-emoji sequence: a base pictograph plus any trailing variation
// selector / ZWJ-joined pictograph / skin-tone modifier. Also matches flag pairs
// (two regional indicators). Plain arrows (→) and typographic punctuation are
// NOT pictographic, so they're preserved.
const EMOJI_SEQ =
  /[\u{1F1E6}-\u{1F1FF}]{2}|\p{Extended_Pictographic}(?:️|‍\p{Extended_Pictographic}|[\u{1F3FB}-\u{1F3FF}])*/gu;
const EMOJI_LEFTOVER = /[️‍\u{1F3FB}-\u{1F3FF}]/gu;

function countEmoji(s) {
  if (!s) return 0;
  const m = s.match(EMOJI_SEQ);
  return m ? m.length : 0;
}
function stripEmoji(s) {
  if (!s) return s;
  return s.replace(EMOJI_SEQ, "").replace(EMOJI_LEFTOVER, "");
}
/** Clean a single-line field: strip emoji, collapse the whitespace it leaves. */
function cleanField(s) {
  if (!s) return s;
  return stripEmoji(s).replace(/[ \t]{2,}/g, " ").trim();
}
/** Clean a markdown body: strip emoji outside code fences, tidy whitespace. */
function cleanBody(body) {
  if (!body) return body;
  const lines = body.replace(/\r\n/g, "\n").split("\n");
  let inFence = false;
  const out = lines.map((l) => {
    if (/^```/.test(l.trim())) { inFence = !inFence; return l; }
    if (inFence) return l;
    return stripEmoji(l).replace(/[ \t]{2,}/g, " ").replace(/[ \t]+$/g, "");
  });
  return out.join("\n").replace(/\n{3,}/g, "\n\n");
}

/* ── inline image handling ────────────────────────────────────────────────── */
function ensureInline(body, ranked) {
  let inlineCount = 0;
  // 1. Replace {{SCREENSHOT}} sentinels with distinct, ranked images.
  if (body.includes("{{SCREENSHOT}}")) {
    // Prefer images other than the cover (ranked[0]) for variety, then wrap.
    const pool = [...ranked.slice(1), ranked[0]];
    let pi = 0;
    const next = () => { const img = pool[pi % pool.length]; pi++; inlineCount++; return imgMd(img); };
    return { body: body.replace(/\{\{SCREENSHOT\}\}/g, next), inlineCount };
  }
  // 2. Already has a screenshot embedded — leave it (idempotent).
  if (/!\[[^\]]*\]\(\/blog\/screenshots\//.test(body)) return { body, inlineCount: 0 };
  // 3. Inject up to MAX_INLINE distinct images after headings.
  if (MAX_INLINE <= 0) return { body, inlineCount: 0 };
  const lines = body.split("\n");
  const h2 = lines.map((l, i) => (/^##\s+/.test(l) ? i : -1)).filter((i) => i >= 0);
  if (h2.length === 0) return { body, inlineCount: 0 };
  const points = [h2[0]];
  if (MAX_INLINE > 1 && h2.length >= 3) points.push(h2[Math.floor(h2.length / 2)]);
  const picks = ranked.slice(1, 1 + points.length); // distinct from cover
  // Insert bottom-up so earlier indices stay valid.
  const plan = points
    .map((p, idx) => ({ p, img: picks[idx] || ranked[0] }))
    .sort((a, b) => b.p - a.p);
  for (const { p, img } of plan) { lines.splice(p + 1, 0, "", imgMd(img), ""); inlineCount++; }
  return { body: lines.join("\n"), inlineCount };
}

/* ── per-post transform ───────────────────────────────────────────────────── */
function upgrade(post) {
  const ranked = rank(post);
  const emojiRemoved =
    countEmoji(post.title) + countEmoji(post.excerpt) + countEmoji(post.body) +
    countEmoji(post.seoTitle) + countEmoji(post.seoDescription);

  const title = cleanField(post.title);
  const excerpt = cleanField(post.excerpt);
  const seoTitle = cleanField(post.seoTitle);
  const seoDescription = cleanField(post.seoDescription);
  const cleanedBody = cleanBody(post.body || "");
  const { body, inlineCount } = ensureInline(cleanedBody, ranked);

  const coverImage = post.coverImage || `${BASE}/${ranked[0].f}`;
  const coverAdded = !post.coverImage;

  const data = {};
  if (title !== post.title) data.title = title;
  if (excerpt !== (post.excerpt ?? "")) data.excerpt = excerpt;
  if ((seoTitle ?? null) !== (post.seoTitle ?? null)) data.seoTitle = seoTitle;
  if ((seoDescription ?? null) !== (post.seoDescription ?? null)) data.seoDescription = seoDescription;
  if (body !== (post.body ?? "")) data.body = body;
  if (coverImage !== post.coverImage) data.coverImage = coverImage;

  return { data, emojiRemoved, inlineCount, coverAdded, coverImage, changed: Object.keys(data).length > 0 };
}

/* ── run ──────────────────────────────────────────────────────────────────── */
function dbHost() {
  try { return new URL(process.env.DATABASE_URL).host; } catch { return "(unknown)"; }
}

async function main() {
  const where = SLUG ? { slug: SLUG } : TAG ? { tags: { has: TAG } } : { published: true };
  const posts = await db.blogPost.findMany({
    where,
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    ...(LIMIT ? { take: LIMIT } : {}),
  });

  console.log(`\nblog-upgrade — ${APPLY ? (CONFIRM ? "APPLY (writing)" : "APPLY blocked (missing --yes)") : "DRY RUN"}`);
  console.log(`DB host: ${dbHost()}`);
  console.log(`Target : ${SLUG ? `slug=${SLUG}` : TAG ? `tag=${TAG}` : "all published"}  →  ${posts.length} post(s)\n`);

  if (APPLY && !CONFIRM) {
    console.log("Refusing to write without --yes (or ALLOW_APPLY=1). Re-run with --yes to confirm.\n");
    await db.$disconnect();
    process.exit(1);
  }

  let changed = 0, emoji = 0, covers = 0, inlines = 0;
  const samples = [];
  for (const post of posts) {
    const u = upgrade(post);
    if (u.emojiRemoved) emoji += u.emojiRemoved;
    if (u.coverAdded) covers += 1;
    inlines += u.inlineCount;
    if (u.changed) {
      changed += 1;
      if (samples.length < SAMPLES) samples.push({ post, u });
      if (APPLY && CONFIRM) await db.blogPost.update({ where: { id: post.id }, data: u.data });
    }
  }

  // ── sample before/after ────────────────────────────────────────────────
  for (const { post, u } of samples) {
    console.log("────────────────────────────────────────────────────────");
    console.log(`slug: ${post.slug}`);
    if (u.data.title) console.log(`  title:  "${post.title}"\n       → "${u.data.title}"`);
    console.log(`  emoji removed: ${u.emojiRemoved}   inline images added: ${u.inlineCount}`);
    console.log(`  cover: ${post.coverImage ?? "(none)"} ${u.coverAdded ? `→ ${u.coverImage}  [ADDED]` : "(kept)"}`);
    const fields = Object.keys(u.data).join(", ");
    console.log(`  fields to update: ${fields}`);
    if (u.data.body) {
      const firstImg = u.data.body.split("\n").find((l) => /!\[[^\]]*\]\(\/blog\/screenshots\//.test(l));
      if (firstImg) console.log(`  inserted image md: ${firstImg.trim()}`);
    }
  }

  console.log("\n════════════════════ SUMMARY ════════════════════");
  console.log(`posts scanned          : ${posts.length}`);
  console.log(`posts that would change : ${changed}${APPLY && CONFIRM ? " (written)" : ""}`);
  console.log(`emoji occurrences fixed : ${emoji}`);
  console.log(`covers added            : ${covers}`);
  console.log(`inline images added     : ${inlines}`);
  console.log(APPLY && CONFIRM ? "\nDONE — changes written.\n" : "\nDRY RUN — nothing written. Re-run with --apply --yes to write.\n");

  await db.$disconnect();
}

main().catch(async (e) => {
  console.error(e);
  await db.$disconnect();
  process.exit(1);
});

