// Boundary-aware keyword match so short keywords ("ai", "mx") don't false-match
// inside unrelated words ("expl-ai-ned", "e-mai-l"). Regexes are built once.
const KW_RE = new Map();
function matchKw(hay, kw) {
  let re = KW_RE.get(kw);
  if (!re) {
    const esc = kw.trim().replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    re = new RegExp(`(?:^|[^a-z0-9])${esc}(?:[^a-z0-9]|$)`, "i");
    KW_RE.set(kw, re);
  }
  return re.test(hay);
}

/**
 * Rank the available screenshots by relevance to a post.
 * Returns { cover, pool } where `cover` is the single best fit (falling back to
 * the generic deploy-wizard shot when nothing matches) and `pool` is the list of
 * *other* screenshots that genuinely matched the topic (score > 0), best first —
 * so only topic-relevant images are ever embedded inline.
 */
function rank(post) {
  const hay = ` ${post.title} ${(post.tags || []).join(" ")} ${post.category} `.toLowerCase();
  const scored = AVAILABLE.map((img) => ({ img, score: img.kw.reduce((n, k) => n + (matchKw(hay, k) ? 1 : 0), 0) }));
  scored.sort((a, b) => b.score - a.score);
  const cover = scored[0].score > 0 ? scored[0].img : AVAILABLE.find((i) => i.f === "deploy-wizard.png");
  const pool = scored.filter((s) => s.score > 0 && s.img !== cover).map((s) => s.img);
  return { cover, pool };
}
const imgMd = (img) => `![${img.alt}](${BASE}/${img.f})`;

