/* ── inline image handling ────────────────────────────────────────────────── */
// `cover` is the post's cover image; `pool` is the topic-relevant others.
function ensureInline(body, cover, pool) {
  let inlineCount = 0;
  // 1. Replace {{SCREENSHOT}} sentinels with distinct topic-relevant images
  //    (falling back to the cover if the topic only matched one screenshot).
  if (body.includes("{{SCREENSHOT}}")) {
    const cycle = pool.length ? pool : [cover];
    let pi = 0;
    const next = () => { const img = cycle[pi % cycle.length]; pi++; inlineCount++; return imgMd(img); };
    return { body: body.replace(/\{\{SCREENSHOT\}\}/g, next), inlineCount };
  }
  // 2. Already has a screenshot embedded — leave it (idempotent).
  if (/!\[[^\]]*\]\(\/blog\/screenshots\//.test(body)) return { body, inlineCount: 0 };
  // 3. Inject up to MAX_INLINE genuinely topic-relevant images after headings.
  //    Only images that actually matched the topic (pool) are injected — never a
  //    random filler shot — so a single-topic post simply gets fewer inlines.
  if (MAX_INLINE <= 0 || pool.length === 0) return { body, inlineCount: 0 };
  const lines = body.split("\n");
  const h2 = lines.map((l, i) => (/^##\s+/.test(l) ? i : -1)).filter((i) => i >= 0);
  if (h2.length === 0) return { body, inlineCount: 0 };
  const want = Math.min(MAX_INLINE, pool.length);
  const points = [h2[0]];
  if (want > 1 && h2.length >= 3) points.push(h2[Math.floor(h2.length / 2)]);
  const picks = pool.slice(0, points.length);
  // Insert bottom-up so earlier indices stay valid.
  const plan = points.map((p, idx) => ({ p, img: picks[idx] })).filter((x) => x.img).sort((a, b) => b.p - a.p);
  for (const { p, img } of plan) { lines.splice(p + 1, 0, "", imgMd(img), ""); inlineCount++; }
