// Legitimate typographic symbols that Unicode also classes as pictographic —
// keep them, they're real text (trademark, copyright, registered, numero…).
const KEEP = new Set(["™", "©", "®", "℠", "№", "℅", "℗"]);

function countEmoji(s) {
  if (!s) return 0;
  const m = s.match(EMOJI_SEQ);
  return m ? m.filter((x) => !KEEP.has(x)).length : 0;
}
function stripEmoji(s) {
  if (!s) return s;
  return s.replace(EMOJI_SEQ, (m) => (KEEP.has(m) ? m : "")).replace(EMOJI_LEFTOVER, "");
}

